function formatName(firstName, lastName) {
  var f = firstName.trim();
  var l = lastName.trim();
  f = f.charAt(0).toUpperCase() + f.slice(1).toLowerCase();
  l = l.charAt(0).toUpperCase() + l.slice(1).toLowerCase();
  return l + ', ' + f;
}

function* counter(start, step) {
  while (true) {
    yield start;
    start += step;
  }
}
